return {require_c_intrinsics=true,source=[=[@/opt/mudlet/mudlet-lua/lua/Other.lua]=],register_dump_hex=[=[]=],register_reference=[=[local handlers,findStringEventHandler,handlerIdsToHandlers,highestHandlerId



























































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































































return function(event, func, isOneShot)
    if type(event) ~= "string" then
      error(
      string.format(
